import json, re, random, chess, sys, time
R = json.load(open(sys.argv[1]))
C = [(re.compile(p), r) for p, r in R]
def run(fen):
    for p, r in C: fen = p.sub(r, fen)
    return fen.split("\n")
def ref(fen):
    b = chess.Board(fen); s=set()
    for m in b.legal_moves:
        if m.promotion and m.promotion != chess.QUEEN: continue
        bc=b.copy(); bc.push(m); s.add(" ".join(bc.fen().split(" ")[:-2]))
    return s
def ok(fen):
    ours=[" ".join(x.split(" ")[:-2]) for x in run(fen)]
    exp=ref(fen)
    for x in ours:
        if not (x in exp or x.rpartition(" ")[0]+" -" in exp): return False, ours, exp
    return len(ours)==len(exp), ours, exp
f="<REDACTED_B64> w kq - 0 1"
print(repr("\n".join(run(f))))
random.seed(int(sys.argv[2]) if len(sys.argv)>2 else 0)
n=0; t=time.time(); bad=0
for g in range(400):
    b=chess.Board()
    while not b.is_game_over() and b.ply()<200:
        if b.turn==chess.WHITE:
            fen=b.fen(); n+=1
            r,o,e=ok(fen)
            if not r:
                bad+=1
                if bad<4: print("FAIL",fen,sorted(set(o)-e),sorted(e-set(o)))
        ms=list(b.legal_moves)
        # bias toward captures/promotions/castling
        b.push(random.choice(ms))
print(n,"positions",bad,"bad",time.time()-t,"s")
EOF
